function ensureGooglePlaces(){if(typeof window==='undefined')return Promise.resolve(false);if(window.google?.maps?.places)return Promise.resolve(true);const key=import.meta?.env?.VITE_GOOGLE_MAPS_API_KEY;if(!key)return Promise.resolve(false);if(googlePlacesLoading)return googlePlacesLoading;googlePlacesLoading=new Promise(resolve=>{const existing=document.querySelector('script[data-onkotaxi-google-places]');if(existing){existing.addEventListener('load',()=>resolve(true));existing.addEventListener('error',()=>resolve(false));return}const script=document.createElement('script');script.dataset.onkotaxiGooglePlaces='true';script.src=`https://maps.googleapis.com/maps/api/js?key=${key}&libraries=places&language=pl&region=PL`;script.async=true;script.defer=true;script.onload=()=>resolve(true);script.onerror=()=>resolve(false);document.head.appendChild(script)});return googlePlacesLoading}

