function normalizeDB(raw){const safe=raw&&typeof raw==='object'?raw:{};return {...base,...safe,users:Array.isArray(safe.users)?safe.users:base.users,patients:Array.isArray(safe.patients)?safe.patients:base.patients,docs:Array.isArray(safe.docs)?safe.docs:base.docs,rides:Array.isArray(safe.rides)?safe.rides:base.rides,ads:Array.isArray(safe.ads)?safe.ads:base.ads,alerts:Array.isArray(safe.alerts)?safe.alerts:base.alerts}}function load(){try{const parsed=JSON.parse(localStorage.onkoMVP236||'null');const db=normalizeDB(parsed);localStorage.onkoMVP236=JSON.stringify(db);return db}catch{localStorage.onkoMVP236=JSON.stringify(base);return base}}function uid(){return Math.random().toString(36).slice(2,9)}function useDB(){const[d,setD]=useState(load());return[d,x=>{const db=normalizeDB(x);setD({...db});localStorage.onkoMVP236=JSON.stringify(db)}]}
